 * @throws OrderWarehouseStorageProcessingFailedException 창고 보관 처리 실패 시
 */
@Transactional
public Order createInstantOrder(User buyer, SaleBid saleBid, Long addressId,
                                boolean isWarehouseStorage, PaymentRequestDto paymentRequest) {
